// 3. กรองข้อมูล: ตรวจสอบ column "due_date_to" ว่าหลังจากวันนี้อีก 3 เดือน และยังไม่เคยส่งสำเร็จ
const results = [];
const today = new Date();

const targetMonths = 3;
const minTargetDate = new Date();
minTargetDate.setMonth(today.getMonth() + targetMonths);
minTargetDate.setDate(minTargetDate.getDate() - 15); // ช่วงเริ่มต้น window (-15 วัน)

for (const item of $input.all()) {
  const row = item.json;

  const name = row['ชื่อ'] || row['name'] || row['Name'] || '';
  const email = row['email'] || row['Email'] || row['อีเมล'] || '';
  const status = row['status'] || row['Status'] || row['สถานะ'] || '';
  const dueDateRaw = row['due_date_to'] || row['dueDate'] || '';

  // ข้ามรายการที่ไม่มี email หรือเคยส่งสำเร็จไปแล้ว
  if (!email || status === 'สำเร็จ' || status === 'Sent') {
    continue;
  }

  let isMatchedDate = true;
  if (dueDateRaw) {
    const dueDate = new Date(dueDateRaw);
    if (!isNaN(dueDate.getTime())) {
      isMatchedDate = dueDate >= minTargetDate;
    }
  }

  if (isMatchedDate) {
    results.push({
      json: {
        ...row,
        resolved_name: name || 'คุณลูกค้า',
        resolved_email: email,
        resolved_due_date: dueDateRaw
      }
    });
  }
}

return results;

// 4.1-4.2 เตรียม Mail Body Template โดยใส่ "ชื่อ"
const record = $input.item.json;
const name = record.resolved_name;
const email = record.resolved_email;
const dueDate = record.resolved_due_date;

// สร้าง Message-ID เฉพาะสำหรับใช้อ้างอิง
const domain = 'automail.internal';
const customMessageId = `<n8n-${Date.now()}-${Math.random().toString(36).substring(2, 9)}@${domain}>`;

const subject = `[แจ้งเตือนครบกำหนด] เรียน ${name} กำหนดการของท่านใกล้ครบกำหนดในอีก 3 เดือน`;

const htmlBody = `
<div style="font-family: 'Sarabun', Arial, sans-serif; line-height: 1.6; color: #333;">
  <h2 style="color: #1a73e8;">แจ้งเตือนกำหนดการ</h2>
  <p>เรียนคุณ <strong>${name}</strong>,</p>
  <p>ระบบขอแจ้งเตือนว่ารายการของท่านมีกำหนดครบกำหนดในวันที่: <strong>${dueDate || 'อีก 3 เดือนข้างหน้า'}</strong></p>
  <p>หากท่านมีข้อสงสัยหรือต้องการดำเนินการต่อ สามารถตอบกลับ (Reply) อีเมลฉบับนี้ได้ทันทีครับ</p>
  <hr style="border: none; border-top: 1px solid #e0e0e0; margin: 20px 0;" />
  <p style="font-size: 12px; color: #777;">อีเมลนี้ถูกส่งโดยระบบอัตโนมัติ (Reference ID: ${customMessageId})</p>
</div>
`;

return {
  json: {
    ...record,
    mail_subject: subject,
    mail_html: htmlBody,
    generated_message_id: customMessageId
  }
};

// บันทึก log สถานะสำเร็จเพื่อนำไปรวมส่งรายงานสรุป
const template = $('4.1-4.2 Build Mail Template').item.json;
return {
  json: {
    is_success: true,
    name: template.resolved_name,
    email: template.resolved_email,
    message_id: template.generated_message_id,
    reason: 'Success'
  }
};

// บันทึก log สถานะไม่สำเร็จเพื่อนำไปรวมส่งรายงานสรุป
const template = $('4.1-4.2 Build Mail Template').item.json;
const errMsg = $input.item.json.error?.message || 'SMTP Error';
return {
  json: {
    is_success: false,
    name: template.resolved_name,
    email: template.resolved_email,
    message_id: template.generated_message_id,
    reason: errMsg
  }
};

// 5. สรุปผลการส่ง Auto Email ทั้งหมดในรอบนี้
let successLogs = [];
let failLogs = [];

try {
  successLogs = $('Log Success Result').all().map(i => i.json);
} catch (e) {}

try {
  failLogs = $('Log Failure Result').all().map(i => i.json);
} catch (e) {}

const totalSuccess = successLogs.length;
const totalFailed = failLogs.length;
const totalProcessed = totalSuccess + totalFailed;

const nowStr = new Date().toLocaleString('th-TH', { timeZone: 'Asia/Bangkok' });

let htmlReport = `
<div style="font-family: Arial, sans-serif; line-height: 1.5; color: #222;">
  <h2>📊 รายงานผลการส่ง Auto Email ประจำรอบ (Service Account)</h2>
  <p><strong>เวลาประมวลผล:</strong> ${nowStr}</p>
  <table border="1" cellpadding="8" cellspacing="0" style="border-collapse: collapse; width: 100%; max-width: 600px;">
    <tr style="background-color: #f2f2f2;"><th>รายการ</th><th>จำนวน</th></tr>
    <tr><td>ทั้งหมดที่เข้าเงื่อนไข</td><td><strong>${totalProcessed}</strong></td></tr>
    <tr style="color: green;"><td>ส่งสำเร็จ (4.3.T)</td><td><strong>${totalSuccess}</strong></td></tr>
    <tr style="color: red;"><td>ไม่สำเร็จ (4.3.F)</td><td><strong>${totalFailed}</strong></td></tr>
  </table>
`;

if (totalFailed > 0) {
  htmlReport += `
  <h3 style="color: red; margin-top: 20px;">⚠️ รายการที่ไม่สำเร็จ:</h3>
  <ul>
    ${failLogs.map(f => `<li><strong>${f.name}</strong> (${f.email}) - เหตุผล: ${f.reason}</li>`).join('')}
  </ul>
  `;
}

htmlReport += `
  <hr style="margin-top: 30px; border: none; border-top: 1px solid #ccc;" />
  <p style="font-size: 12px; color: #666;">รายงานนี้สร้างขึ้นโดยระบบอัตโนมัติ n8n (Google Service Account)</p>
</div>
`;

return {
  json: {
    total_processed: totalProcessed,
    total_success: totalSuccess,
    total_failed: totalFailed,
    report_html: htmlReport,
    report_subject: `[Auto Mail Report] สรุปผลการส่งอีเมล (${totalSuccess} สำเร็จ, ${totalFailed} ล้มเหลว)`
  }
};
